import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, mul, add, vec2 } from 'three/tsl';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Resolve text items
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Create root group
  const root = new Group();
  root.userData.handlers = {};

  // ---------- BACKDROP (gradient plane) ----------
  // Visual spec gradient: use colors from config.intent?.visualSpec?.colors or fallback
  const colors = (config.intent?.visualSpec?.colors) || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // Gradient plane (7x6 units at z = -2.5)
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.0,
  });
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- TEXT ----------
  // Create text objects from items
  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 0.34, // default headline size in scene units
      color: colors.ink,
      align: 'center',
      maxWidthPx: undefined,
      letterSpacingPx: undefined,
    };
    const txtObj = ctx.fontAtlas.createText(item.text, opts);
    txtObj.position.set(0, 0, 0);
    root.add(txtObj);
  }

  // ---------- SPRITE PLANE ----------
  // Atlas region dimensions
  const region = { x: 0, y: 0, width: 512, height: 320 };
  const aspect = region.width / region.height; // 1.6
  const planeWidth = aspect; // 1 unit height baseline
  const planeHeight = 1;

  const planeGeom = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });

  const plane = new Mesh(planeGeom, material);
  // Position from spec (adapter will apply final transform)
  plane.position.set(0, 0, 0);
  root.add(plane);

  // Load texture and apply UV transform for atlas region
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    // UV transform node: offset + scale
    const uvNode = uv();
    const scaleNode = vec2(region.width / tex.image.width, region.height / tex.image.height);
    const offsetNode = vec2(region.x / tex.image.width, region.y / tex.image.height);
    const transformedUV = add(mul(uvNode, scaleNode), offsetNode);
    material.map = texture(tex, transformedUV);
    material.needsUpdate = true;
  });

  // ---------- BILLBOARD BEHAVIOR ----------
  // Simple billboard: align plane to camera each frame via a tiny update handler
  root.userData.update = (camera) => {
    plane.quaternion.copy(camera.quaternion);
  };

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    // Dispose geometry and material
    planeGeom.dispose();
    material.dispose();
    backdropGeom.dispose();
    backdropMat.dispose();

    // No GSAP timelines used, but ensure any exist are killed
    if (root.userData._timelines) {
      root.userData._timelines.forEach((tl) => tl.kill());
    }
    root.userData.handlers = {};
    root.userData.update = null;
  };

  // ---------- APPLY CINEMATIC PRIMITIVES ----------
  const primitivesList = config.cinematicPrimitives ?? [];
  const activePrims = [];
  for (const prim of primitivesList) {
    const p = ctx.primitives[prim.name](root, prim.params);
    activePrims.push(p);
    // Attach cleanup for each primitive
    const prevCleanup = root.userData.cleanup;
    root.userData.cleanup = () => {
      prevCleanup();
      p.cleanup();
    };
  }

  return root;
}
